CREATE TABLE stok_opname_karawang_scan ( id INT AUTO_INCREMENT PRIMARY KEY, rackcode VARCHAR(30) NOT NULL, collie VARCHAR(30) NOT NULL, item VARCHAR(30) NOT NULL, deskripsi VARCHAR(150) NULL, kategori VARCHAR(10) NULL, qty INT NOT NULL DEFAULT 0, id_karyawan INT NULL, waktu_scan DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_collie_scan (collie), KEY idx_rackcode_scan (rackcode), KEY idx_item_scan (item) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE stok_opname_karawang_target ( id INT AUTO_INCREMENT PRIMARY KEY, rackcode VARCHAR(30) NOT NULL, collie VARCHAR(30) NOT NULL, item VARCHAR(30) NOT NULL, deskripsi VARCHAR(150) NULL, kategori VARCHAR(10) NULL, qty INT NOT NULL DEFAULT 0, UNIQUE KEY uq_collie (collie), KEY idx_rackcode (rackcode), KEY idx_item (item) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;